    vocabulary: [["Cosmopolitan","(Adjective) Comfortable with many cultures in one place."],["Metabolise","(Verb) To process and transform (figurative: handle conflict)."],["Catastrophise","(Verb) To interpret events as total disaster."],["Segregation","(Noun) Separation of groups into different spaces."],["Profile","(Verb) To suspect or target based on group traits."],["Infrastructure","(Noun) Basic systems supporting collective activity."],["Resilience","(Noun) Capacity to recover under pressure."],["Fidelity","(Noun) Faithfulness to truth or detail."],["Coexistence","(Noun) Living together despite differences."],["Unfinishedness","(Noun) The state of still being in process."],["Micro-diplomacy","(Noun) Small everyday acts of negotiation between neighbours."],["Underpowered","(Adjective) Lacking sufficient resources or authority."],["Scarcity","(Noun) Insufficient supply."],["Regime","(Noun) An organised system of rules."],["Paradise","(Noun) An ideal perfect place (often mythical)."],["Flatten","(Verb) To oversimplify complex reality."]],
